	"settings.item.retry.maxDelayMs.description":
		"Maximum wait between retries, in ms. When the provider asks us to wait longer than this and no credential or model fallback succeeds, the request fails fast instead of sleeping (e.g. 3-hour Anthropic rate-limit windows). 0 disables the ceiling — to let the session auto-resume through provider-stated quota resets.",
	"settings.item.retry.waitForUsageReset.label": "Wait For Usage Reset",
	"settings.item.retry.waitForUsageReset.description":
		"When a provider reports usage-limit exhaustion with a reset time (5-hour or weekly quota windows on any provider), sleep until the reset instead of failing fast past retry.maxDelayMs. Waits are abortable (Esc) but also hold subagents, so leave off for unattended runs.",
	"settings.item.retry.modelFallback.label": "Retry Model Fallback",
	"settings.item.retry.modelFallback.description": "Allow retry recovery to switch to configured fallback models",
	"settings.item.retry.usageAwareFallback.label": "Usage-Aware Fallback",
	"settings.item.retry.usageAwareFallback.description":
		"Use reliable coding-plan quota reports to prefer same-provider accounts, then configured fallback models, before a hard usage limit. Ordinary configured API keys are excluded.",
	"settings.item.retry.usageReservePct.label": "Reserve Margin",
	"settings.item.retry.usageReservePct.description":
		"Treat a coding-plan model as near its limit below this remaining percentage. Unknown or unmapped usage keeps the primary model.",
