	"settings.item.codexResets.minBlockedMinutes.label": "Codex Auto-Redeem Min Block",
	"settings.item.codexResets.minBlockedMinutes.description":
		"Only auto-redeem when the natural unblock — the latest reset among the exhausted 5h/weekly windows — is at least this many minutes away (don't spend a scarce credit to save a short wait). Raise it (e.g. 360) to ignore 5h-only blocks.",
	"settings.item.codexResets.keepCredits.label": "Codex Auto-Redeem Reserve",
	"settings.item.codexResets.keepCredits.description":
		"Never auto-spend below this many saved resets (0 = the last credit may be spent automatically). Credits about to expire are exempt — a reserved credit that expires preserves nothing.",
	"settings.item.codexResets.salvageHorizonHours.label": "Codex Reset Salvage Horizon",
	"settings.item.codexResets.salvageHorizonHours.description":
		"Spend a saved Codex reset automatically when it would otherwise expire within this many hours and either chat window (5h or weekly) has meaningful usage to restore (0 disables expiry salvage).",
	"settings.item.claudeResets.autoRedeem.label": "Claude Auto-Redeem Resets",
	"settings.item.claudeResets.autoRedeem.description":
		"Spend eligible Claude Cedar or Juniper resets automatically. Cedar is spent only for covered limits; Juniper can only recover a sole 5-hour block. unset asks before the first spend, yes spends without prompting, and no disables blocked recovery and expiry salvage.",
	"settings.item.claudeResets.autoRedeem.option.unset.label": "Unset",
	"settings.item.claudeResets.autoRedeem.option.unset.description":
		"Check live eligibility, then ask before spending the first Claude reset.",
	"settings.item.claudeResets.autoRedeem.option.yes.label": "Yes",
	"settings.item.claudeResets.autoRedeem.option.yes.description": "Spend eligible Claude resets without prompting.",
	"settings.item.claudeResets.autoRedeem.option.no.label": "No",
	"settings.item.claudeResets.autoRedeem.option.no.description": "Do not run Claude reset auto-redeem checks.",
	"settings.item.claudeResets.minBlockedMinutes.label": "Claude Auto-Redeem Min Block",
	"settings.item.claudeResets.minBlockedMinutes.description":
		"Only auto-redeem when the natural unblock — the latest reset among the exhausted covered windows — is at least this many minutes away. A 5-hour-only reset is never used for a weekly or model-scoped block.",
	"settings.item.claudeResets.keepCredits.label": "Claude Auto-Redeem Reserve",
	"settings.item.claudeResets.keepCredits.description":
		"Keep at least this many Claude resets banked (0 allows the last eligible reset to be spent automatically). The reserve also applies to expiry salvage.",
	"settings.item.claudeResets.salvageHorizonHours.label": "Claude Reset Salvage Horizon",
	"settings.item.claudeResets.salvageHorizonHours.description":
		"Use a server-selected Cedar reset within this many hours of expiry only when its covered windows have meaningful usage to restore and the grant permits early use or a covered window is exhausted (0 disables salvage).",
	"settings.item.provider.appendOnlyContext.label": "Append-Only Context",
	"settings.item.provider.appendOnlyContext.description":
		"Cache system prompt + tool specs and keep an append-only message log so provider prefix caches (DeepSeek, Xiaomi/SGLang, Anthropic) hit at maximum rate. Auto enables for known prefix-cache providers.",
	"settings.item.provider.appendOnlyContext.option.auto.label": "Auto",
	"settings.item.provider.appendOnlyContext.option.auto.description":
		"Enable for known prefix-cache providers (recommended)",
	"settings.item.provider.appendOnlyContext.option.on.label": "On",
	"settings.item.provider.appendOnlyContext.option.on.description": "Always enable append-only context",
	"settings.item.provider.appendOnlyContext.option.off.label": "Off",
	"settings.item.provider.appendOnlyContext.option.off.description": "Disable append-only context",
	"settings.item.telemetry.otlpExportEnabled.label": "OTLP Telemetry Export",
	"settings.item.telemetry.otlpExportEnabled.description":
		"Allow OMP to export traces, logs, and metrics using OTEL_* endpoints. Changes take effect on the next launch.",
	"settings.item.advisor.enabled.label": "Enable Advisor",
	"settings.item.advisor.enabled.description":
		"Pair a second model (assigned to the 'advisor' role) that passively reviews each turn and injects notes.",
	"settings.item.advisor.syncBacklog.label": "Advisor Sync Backlog",
	"settings.item.advisor.syncBacklog.description":
		"Pause the main agent for up to 30 seconds if the advisor falls behind by this many turns. Off disables catch-up delays.",
	"settings.item.advisor.immuneTurns.label": "Advisor Immune Turns",
	"settings.item.advisor.immuneTurns.description":
		"After an advisor concern or blocker interrupts, route further concerns/blockers non-interruptingly for this many primary turns.",
	"settings.item.advisor.immuneTurns.option.0.label": "0 turns",
	"settings.item.advisor.immuneTurns.option.0.description": "Allow every concern/blocker to interrupt.",
	"settings.item.advisor.immuneTurns.option.1.label": "1 turn",
	"settings.item.advisor.immuneTurns.option.2.label": "2 turns",
