	"settings.item.advisor.immuneTurns.option.4.label": "4 turns",
	"settings.item.advisor.immuneTurns.option.5.label": "5 turns",
	"settings.item.advisor.maxNotesPerUpdate.label": "Advisor Max Notes Per Update",
	"settings.item.advisor.maxNotesPerUpdate.description":
		"Maximum non-blocker advice notes accepted per advisor prompt update (1–32; UI offers 1–5 quick picks). Blockers are exempt.",
	"settings.item.advisor.maxNotesPerUpdate.option.1.label": "1 note",
	"settings.item.advisor.maxNotesPerUpdate.option.1.description": "Anti-flood (strict).",
