	"settings.item.task.softRequestBudgetNotice.label": "Soft Request Budget Notice",
	"settings.item.task.softRequestBudgetNotice.description":
		"Inject one steering notice when a subagent crosses its soft request budget, asking it to wrap up before the 1.5x forced-yield stop.",
	"settings.item.task.maxEffort.label": "Maximum Per-Spawn Effort",
	"settings.item.task.maxEffort.description":
		"Maximum reasoning effort allowed for the task tool's per-spawn effort hint. Lower values prevent callers from escalating subagents above this ceiling; the default preserves the model's full range.",
	"settings.item.task.maxEffort.option.minimal.label": "min",
	"settings.item.task.maxEffort.option.minimal.description": "Very brief reasoning (~1k tokens)",
