	"settings.item.task.maxEffort.option.xhigh.label": "xhigh",
	"settings.item.task.maxEffort.option.xhigh.description": "Extended reasoning (~32k tokens)",
	"settings.item.task.maxEffort.option.max.label": "max",
	"settings.item.task.maxEffort.option.max.description": "Maximum reasoning the model supports",
	"settings.item.task.prewalk.label": "Generic Task Prewalk",
	"settings.item.task.prewalk.description":
		"Arm prewalk for the bundled generic `task` subagent: it starts on its resolved model, plans and begins the implementation, then hands off to the 'smol' role at its first edit/write. Per-agent overrides (task.agentPrewalk, configured from the /agents hub) and user agent `prewalk` frontmatter apply regardless of this toggle.",
	"settings.item.task.showResolvedModelBadge.label": "Show Resolved Model Badge",
