	"settings.item.browser.cdpUrl.label": "Browser CDP URL",
	"settings.item.browser.cdpUrl.description":
		"Default HTTP CDP discovery endpoint (for example http://127.0.0.1:9222) to attach to instead of launching a browser. Explicit app.cdp_url or app.path on the tool call take precedence.",
	"settings.item.browser.relay.label": "Browser Relay",
	"settings.item.browser.relay.description":
		"Drive your own Chrome tabs through the omp browser relay. Install the extension once (`omp browser-relay install`); the relay server auto-starts when the browser prelude needs it. Takes precedence over Browser CDP URL; set PI_BROWSER_RELAY=0 or PI_BROWSER_RELAY=1 to override.",
	"settings.item.browser.relayUrl.label": "Browser Relay URL",
	"settings.item.browser.relayUrl.description": "omp browser relay endpoint (default http://127.0.0.1:9224).",
	"settings.item.browser.headless.label": "Headless Browser",
	"settings.item.browser.headless.description": "Launch browser in headless mode (disable to show browser UI)",
	"settings.item.browser.cmux.label": "cmux Browser",
	"settings.item.browser.cmux.description":
		"Use cmux WKWebView surfaces for browser automation when a cmux socket is available. Set PI_BROWSER_CMUX=0 or PI_BROWSER_CMUX=1 to override.",
	"settings.item.browser.tern.label": "Tern Browser",
	"settings.item.browser.tern.description":
		"Inside a Tern pane, open browser tabs as picture-in-pictures over omp's pane (native web view) instead of headless Chromium; falls back to Chromium when no Tern window can host them. Explicit app options, the relay and Browser CDP URL take precedence; headed:false or app.tern:false opts one open out. Set PI_BROWSER_TERN=0 or PI_BROWSER_TERN=1 to override.",
	"settings.item.browser.freezeOnTurnEnd.label": "Freeze Browser Tabs On Turn End",
	"settings.item.browser.freezeOnTurnEnd.description":
		"Freeze OMP-owned headless browser tabs when a turn settles so animated pages stop burning CPU/GPU while idle. Tabs unfreeze automatically on next use; pass persist:true on open to opt a tab out.",
	"settings.item.browser.idleCloseSec.label": "Browser Idle Close Timeout",
	"settings.item.browser.idleCloseSec.description":
		"Close OMP-owned headless browser tabs and Tern browser picture-in-pictures idle longer than this many seconds (0 = never; session dispose still reaps). Never touches relay/CDP/spawned browsers or other sessions' tabs.",
	"settings.item.browser.idleCloseSec.option.0.label": "Never",
